with flattened_attrs as (select id, effective_from, currency, tier_limits, aggregate(tier_prices, 0.0D, (acc, p) -> acc + p, acc -> round(acc / size(tier_prices), 2)) as avg_tier_price, zip_with(tier_prices, discounts, (p, d) -> round(p * (1 - d), 2)) as net_prices, element_at(tier_prices, 1) as entry_price, slice(tier_limits, 1, 2) as first_two_limits from price_tiers where effective_from > '2025-05-22') select *, cume_dist() over (partition by currency order by entry_price desc nulls first) entry_price_cume_dist, avg(entry_price) over (partition by currency order by entry_price, id rows between 5 preceding and current row) entry_price_avg_5, row_number() over (partition by currency order by avg_tier_price, id) seq_no from flattened_attrs
